const POLBENG_LOGO_JPEG_BASE64 = "";

function escapePdf(value: string) {
  return value.replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
}

function ascii(value: string) {
  return Buffer.from(value, "ascii");
}

export function createPdfWithPolbengLogo(lines: string[]) {
  const logo = Buffer.from(POLBENG_LOGO_JPEG_BASE64, "base64");
  const body = lines.slice(3);
  const pages: string[][] = [];
  pages.push(body.slice(0, 45));
  for (let index = 45; index < body.length; index += 52) {
    pages.push(body.slice(index, index + 52));
  }
  if (!pages.length) pages.push(["Laporan audit belum memiliki isi."]);

  const objects: Buffer[] = [];
  objects[1] = ascii("<< /Type /Catalog /Pages 2 0 R >>");
  objects[3] = ascii("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
  objects[4] = Buffer.concat([
    ascii(`<< /Type /XObject /Subtype /Image /Width 71 /Height 72 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${logo.length} >>\nstream\n`),
    logo,
    ascii("\nendstream"),
  ]);

  const pageIds: number[] = [];
  pages.forEach((pageLines, pageIndex) => {
    const pageId = 5 + pageIndex * 2;
    const contentId = pageId + 1;
    pageIds.push(pageId);
    const firstPageHeader = pageIndex === 0
      ? [
          "q 58 0 0 59 48 764 cm /Logo Do Q",
          "BT /F1 12 Tf 120 807 Td 16 TL",
          `(${escapePdf(lines[0] || "LAPORAN AUDIT MUTU INTERNAL NONAKADEMIK")}) Tj T*`,
          `(${escapePdf(lines[1] || "POLITEKNIK NEGERI BENGKALIS")}) Tj`,
          "ET",
          "0.8 w 48 748 m 547 748 l S",
        ]
      : [];
    const startY = pageIndex === 0 ? 730 : 795;
    const commands = [
      ...firstPageHeader,
      "BT",
      "/F1 10 Tf",
      `48 ${startY} Td`,
      "14 TL",
      ...pageLines.map((line) => `(${escapePdf(line)}) Tj T*`),
      "ET",
      "BT /F1 9 Tf 48 28 Td",
      `(Halaman ${pageIndex + 1} dari ${pages.length}) Tj`,
      "ET",
    ].join("\n");
    objects[pageId] = ascii(
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> /XObject << /Logo 4 0 R >> >> /Contents ${contentId} 0 R >>`,
    );
    objects[contentId] = ascii(
      `<< /Length ${Buffer.byteLength(commands, "ascii")} >>\nstream\n${commands}\nendstream`,
    );
  });

  objects[2] = ascii(
    `<< /Type /Pages /Kids [${pageIds.map((id) => `${id} 0 R`).join(" ")}] /Count ${pageIds.length} >>`,
  );

  const chunks: Buffer[] = [ascii("%PDF-1.4\n")];
  const offsets: number[] = [0];
  let size = chunks[0].length;
  for (let id = 1; id < objects.length; id += 1) {
    offsets[id] = size;
    const object = Buffer.concat([
      ascii(`${id} 0 obj\n`),
      objects[id],
      ascii("\nendobj\n"),
    ]);
    chunks.push(object);
    size += object.length;
  }
  const xrefOffset = size;
  let xref = `xref\n0 ${objects.length}\n0000000000 65535 f \n`;
  for (let id = 1; id < objects.length; id += 1) {
    xref += `${String(offsets[id]).padStart(10, "0")} 00000 n \n`;
  }
  xref += `trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;
  chunks.push(ascii(xref));
  return Buffer.concat(chunks);
}
